CREATE TABLE IF NOT EXISTS game_state(user_id TEXT PRIMARY KEY,body TEXT NOT NULL,rev INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS market_snapshots(at INTEGER PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parental_guard(user_id TEXT PRIMARY KEY,salt TEXT,pin_hash TEXT,failures INTEGER NOT NULL DEFAULT 0,blocked_until INTEGER NOT NULL DEFAULT 0,ticket_hash TEXT,ticket_expires INTEGER NOT NULL DEFAULT 0,auth_hash TEXT,revision INTEGER NOT NULL DEFAULT 0);
